Sure! Here's a JavaScript function that switches the order of adjectives in a sentence:

```javascript
function switchAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i] === "beautiful" || words[i] === "green") {
      adjectives.push(words[i]);
    }
  }

  if (adjectives.length > 1) {
    const firstAdjective = adjectives.shift();
    const secondAdjective = adjectives.pop();
    const newSentence = `${firstAdjective} ${secondAdjective} trees are in the park`;
    return newSentence;
  } else {
    return sentence;
  }
}

const sentence = "Beautiful green trees are in the park";
const newSentence = switchAdjectives(sentence);
console.log(newSentence); // Output: "Green beautiful trees are in the park"
```

