function determineProtocol(inputData) {
  const sourceIP = inputData.sourceIP;
  const destinationIP = inputData.destinationIP;
  const port = inputData.port;
  const payload = inputData.payload;

  if (isIPv6(sourceIP) && isIPv6(destinationIP)) {
    // If both source and destination IP addresses are IPv6, the most relevant protocol is IPv6
    return 'IPv6';
  } else if (isHTTPRequest(port, payload)) {
    // If the port number is 80 (HTTP) and the payload contains a message, the most relevant protocol is HTTP
    return 'HTTP';
  } else if (isUDPPacket(sourceIP, destinationIP, port)) {
    // If both source and destination IP addresses are valid UDP addresses and the port number is not 80, the most relevant protocol is UDP
    return 'UDP';
  } else {
    // If none of the above conditions are met, the input data does not provide enough information to determine the most relevant protocol
    return 'Unknown';
  }
}

function isIPv6(ipAddress) {
  // Regular expression pattern to match IPv6 addresses
  const ipv6Pattern = /^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/;
