    vowels = 'aeiou'
    vowel_consonant_combinations = []
    for vowel in vowels:
        if vowel in word:
            vowel_consonant_combinations.append((vowel, word[word.index(vowel):]))
    return vowel_consonant_combinations

def count_frequency(vowel_consonant_combinations):
    frequency = {}
    for vowel, consonant in vowel_consonant_combinations:
        if vowel not in frequency:
            frequency[vowel] = {}
        if consonant not in frequency[vowel]:
            frequency[vowel][consonant] = 0
        frequency[vowel][consonant] += 1
    return frequency

def sort_combinations(frequency):
