using UnityEngine.Visualization;

public class MusicVisualizer : MonoBehaviour
{
    public AudioSource audioSource;
    public Visualizer visualizer;

    void Start()
    {
        if (audioSource == null)
        {
            audioSource = GetComponent<AudioSource>();
        }

        if (visualizer == null)
        {
            visualizer = GetComponent<Visualizer>();
        }
    }

    void Update()
    {
        float amplitude = audioSource.volume * 0.5f;
        visualizer.SetValue("Amplitude", amplitude);
    }
}
