    """Converts a temperature from one unit to another."""
    if from_unit == "Celsius" and to_unit == "Fahrenheit":
        return temp * 9 / 5 + 32
    elif from_unit == "Fahrenheit" and to_unit == "Celsius":
        return (temp - 32) * 5 / 9
    else:
        raise ValueError("Invalid temperature units")
